    "inlineSchema": "// Prisma Schema for Rural Dispatch Ride-Sharing System\n// Using Prisma 7 with PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"./generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==================== USERS ====================\n\n/// Service users (riders, caregivers, etc.)\nmodel User {\n  uuid     String  @id @default(uuid(7)) @db.Uuid\n  fullName String\n  phone    String  @unique\n  email    String?\n  role     String  @default(\"rider\")\n\n  // SMS Consent (TCPA compliance)\n  smsConsentGiven     Boolean?  @default(false)\n  smsConsentTimestamp DateTime?\n  smsConsentIpAddress String?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  ridesAsRider Ride[] @relation(\"RiderRides\")\n\n  // Indexes\n  @@index([phone])\n  @@index([fullName])\n  @@map(\"users\")\n}\n\n// ==================== ORGANIZATIONS ====================\n\nmodel Organization {\n  id          Int     @id @default(autoincrement())\n  name        String  @unique\n  description String?\n\n  // Contact info\n  contactEmail String?\n  contactPhone String?\n  address      String?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  serviceProviders ServiceProvider[]\n\n  @@index([name])\n  @@map(\"organizations\")\n}\n\n// ==================== SERVICE PROVIDERS (Drivers) ====================\n\nmodel ServiceProvider {\n  uuid        String  @id @default(uuid(7)) @db.Uuid\n  fullName    String\n  phone       String?\n  mobilePhone String?\n\n  // Professional details\n  title          String?\n  organizationId Int?\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n  role           String        @default(\"Driver\")\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  ridesAsDriver Ride[] @relation(\"DriverRides\")\n\n  // Indexes\n  @@index([mobilePhone])\n  @@index([fullName])\n  @@index([role])\n  @@index([organizationId])\n  @@map(\"service_providers\")\n}\n\n// ==================== VEHICLES ====================\n\nmodel Vehicle {\n  uuid         String  @id @default(uuid(7)) @db.Uuid\n  displayName  String\n  fleetId      String? @unique\n  model        String?\n  year         Int?\n  color        String?\n  licensePlate String? @unique\n\n  // Capacity and service area\n  capacity    Int?\n  serviceArea String?\n\n  // Accessibility features\n  walkerAccessible      Boolean @default(false)\n  wheelchairAccessible  Boolean @default(false)\n  serviceAnimalFriendly Boolean @default(false)\n  oxygenTankAccessible  Boolean @default(false)\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  rides Ride[]\n\n  // Indexes\n  @@index([licensePlate])\n  @@index([displayName])\n  @@index([fleetId])\n  @@index([serviceArea])\n  @@map(\"vehicles\")\n}\n\n// ==================== RIDE REQUESTS ====================\n\nmodel Ride {\n  uuid      String @id @default(uuid(7)) @db.Uuid\n  displayId String @unique // Human-readable ID (e.g., RIDE-X7K9)\n\n  // Relationships (Foreign Keys with ON DELETE SET NULL)\n  riderUuid String? @db.Uuid\n  rider     User?   @relation(\"RiderRides\", fields: [riderUuid], references: [uuid], onDelete: SetNull)\n\n  driverUuid String?          @db.Uuid\n  driver     ServiceProvider? @relation(\"DriverRides\", fields: [driverUuid], references: [uuid], onDelete: SetNull)\n\n  vehicleUuid String?  @db.Uuid\n  vehicle     Vehicle? @relation(fields: [vehicleUuid], references: [uuid], onDelete: SetNull)\n\n  // Rider info (for non-registered users or when rider relationship is null)\n  riderName  String?\n  riderPhone String?\n\n  // Addresses\n  pickupAddress  String\n  dropOffAddress String\n\n  // Timing\n  pickupRequestedTime       DateTime\n  dropOffRequestedTime      DateTime?\n  rideStartedActualTime     DateTime?\n  pickupActualTime          DateTime?\n  dropOffActualTime         DateTime?\n  rideCompleteRequestedTime DateTime?\n  rideCompleteActualTime    DateTime?\n\n  // Status\n  rideStatus        Int @default(0)\n  rideRequestStatus Int @default(100)\n\n  // Trip details\n  roundTrip Boolean @default(false)\n  purpose   String?\n  notes     String?\n\n  // Accessibility requirements\n  walkerAccessible      Boolean @default(false)\n  wheelchairAccessible  Boolean @default(false)\n  serviceAnimalFriendly Boolean @default(false)\n  oxygenTankAccessible  Boolean @default(false)\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  notifications Notification[]\n\n  // Indexes\n  @@index([riderUuid])\n  @@index([driverUuid])\n  @@index([vehicleUuid])\n  @@index([rideStatus])\n  @@index([rideRequestStatus])\n  @@index([pickupRequestedTime])\n  @@index([displayId])\n  @@map(\"rides\")\n}\n\n// ==================== NOTIFICATIONS ====================\n\nmodel Notification {\n  uuid String @id @default(uuid(7)) @db.Uuid\n\n  // Relationship\n  rideUuid String? @db.Uuid\n  ride     Ride?   @relation(fields: [rideUuid], references: [uuid], onDelete: Cascade)\n\n  // Notification details\n  notificationType String\n  direction        String // 'inbound' or 'outbound'\n  recipientPhone   String\n  recipientName    String?\n  recipientRole    String // 'rider', 'driver', 'case_manager', 'dispatcher'\n  messageBody      String  @db.Text\n\n  // Twilio/Vonage tracking\n  twilioMessageSid String? @unique\n  twilioStatus     String? @default(\"pending\")\n  errorMessage     String?\n\n  // Timing\n  sentAt      DateTime\n  deliveredAt DateTime?\n\n  // Session management\n  sessionActive   Boolean   @default(true)\n  sessionClosedAt DateTime?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Indexes\n  @@index([rideUuid])\n  @@index([recipientPhone])\n  @@index([twilioMessageSid])\n  @@index([sessionActive])\n  @@index([sentAt])\n  @@map(\"notifications\")\n}\n\n// ==================== SYSTEM USERS (Authentication) ====================\n\nmodel SystemUser {\n  uuid         String  @id @default(uuid(7)) @db.Uuid\n  username     String  @unique\n  passwordHash String\n  fullName     String\n  role         String // 'admin', 'dispatcher', 'driver', 'case_manager'\n  isActive     Boolean @default(true)\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Indexes\n  @@index([username])\n  @@index([role])\n  @@map(\"system_users\")\n}\n\n// ==================== ENUMS (if needed) ====================\n\n// Note: Prisma 7 supports mapped enums, but for flexibility we're using String types\n// You can convert these to enums later if needed:\n//\n// enum UserRole {\n//   RIDER\n//   CAREGIVER\n//   CASE_MANAGER\n// }\n//\n// enum RideStatus {\n//   REQUEST_IN_PROGRESS @map(\"0\")\n//   RIDE_CONFIRMED      @map(\"100\")\n//   // ... etc\n// }\n",
